import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ClientPicker } from '@/components/clients/ClientPicker';
import { DateRangePicker } from '@/components/DateRangePicker';
import { parseInvoiceFilters, type InvoiceFilterState } from '@/lib/types/invoice';

export function InvoiceFilters() {
  const router = useRouter();
  const pathname = usePathname();
  const params = useSearchParams();
  const filters = parseInvoiceFilters(params);

  function update(patch: Partial<InvoiceFilterState>) {
    const next = new URLSearchParams(params);
    for (const [key, value] of Object.entries(patch)) {
      if (value === undefined || value === '' || (key === 'status' && value === 'all')) next.delete(key);
      else next.set(key, String(value));
    }
    router.replace(`${pathname}?${next.toString()}`, { scroll: false });
  }

  return (
    <div className="flex flex-wrap gap-2">
      <Select value={filters.status} onValueChange={(status) => update({ status: status as InvoiceFilterState['status'] })}>
        <SelectTrigger className="w-36"><SelectValue /></SelectTrigger>
        <SelectContent>
          <SelectItem value="all">All</SelectItem>
          <SelectItem value="draft">Draft</SelectItem>
          <SelectItem value="sent">Sent</SelectItem>
          <SelectItem value="paid">Paid</SelectItem>
          <SelectItem value="overdue">Overdue</SelectItem>
        </SelectContent>
      </Select>
      <ClientPicker value={filters.clientId} onSelect={(clientId) => update({ clientId })} />
      <DateRangePicker value={{ from: filters.from, to: filters.to }} onChange={(r) => update(r)} />
    </div>
  );
}

