export function slugify(input: string, maxLength = 64): string {
  const slug = input.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return slug.slice(0, maxLength).replace(/-+$/, '');
}
```

NFKD splits letters like "é" into "e" plus an accent mark, and the regex drops the marks. Any run of other characters becomes one dash. After truncating, any trailing dash is removed. I added 4 tests in apps/web/lib/slugify.test.ts. I'm not sure the ß/ø case passes: those letters don't break apart under NFKD, so they may need a small lookup table.

