import { readFile, readdir } from 'node:fs/promises';
import { join, relative } from 'node:path';

const ROOTS = ['apps', 'services', 'packages'];
const SKIP = new Set(['node_modules', 'dist', '.next', '.turbo', 'coverage']);
const EXT = /\.(ts|tsx|js|mjs)$/;
const MARKER = /\b(TODO|FIXME)\b/g;

async function* walk(dir: string): AsyncGenerator<string> {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    if (SKIP.has(entry.name)) continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else if (EXT.test(entry.name)) yield full;
  }
}

async function main(): Promise<void> {
  const counts = new Map<string, { TODO: number; FIXME: number }>();
  for (const root of ROOTS) {
    for (const pkg of await readdir(root)) {
      const tally = { TODO: 0, FIXME: 0 };
      for await (const file of walk(join(root, pkg))) {
        const text = await readFile(file, 'utf8');
        for (const m of text.matchAll(MARKER)) tally[m[1] as 'TODO' | 'FIXME'] += 1;
      }
      counts.set(relative('.', join(root, pkg)), tally);
    }
  }
  const rows = [...counts].map(([pkg, c]) => ({ package: pkg, TODO: c.TODO, FIXME: c.FIXME, total: c.TODO + c.FIXME }));
  console.table(rows.sort((a, b) => b.total - a.total));
}

await main();

